import {VERSION,RULES,DISTRICTS,ACTIONS,newGame,crewOf,available,districtOwner,territories,score,cost,reserved,income,wages,reachable,validation,addOrder,cancelOrder,equip,odds,resolveWeek,publicState} from './engine.js';
const KEY='gangster-reborn-v2';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('fr-CA',{maximumFractionDigits:0}).format(n)+' $';
const glyph={map:'M3 5l6-2 6 2 6-2v16l-6 2-6-2-6 2V5zm6-2v16m6-14v16',person:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',people:'M14 7a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM3 21v-2a7 7 0 0 1 14 0v2m0-16a3 3 0 0 1 0 6m2 3a6 6 0 0 1 3 5v2',cash:'M2 5h20v14H2V5zm7 7a3 3 0 1 0 6 0 3 3 0 1 0-6 0M5 8h1m12 8h1',shield:'M12 2l8 3v6c0 6-8 11-8 11S4 17 4 11V5l8-3zm-4 9 3 3 5-6',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12zm7 0a3 3 0 1 0 6 0 3 3 0 1 0-6 0',target:'M12 2v4m0 12v4M2 12h4m12 0h4M4 12a8 8 0 1 0 16 0 8 8 0 1 0-16 0m5 0a3 3 0 1 0 6 0 3 3 0 1 0-6 0',key:'M14 4a5 5 0 1 1-3 9l-8 8v-5l7-7a5 5 0 0 1 4-5zm2 3h.01',hand:'M7 13V5a2 2 0 0 1 4 0v6-8a2 2 0 0 1 4 0v8-6a2 2 0 0 1 4 0v7-3a2 2 0 0 1 4 0v7c0 5-4 7-8 7-3 0-5-2-7-4l-4-5a2 2 0 0 1 3-3l3 3',bolt:'M13 2 4 14h7l-1 8 10-13h-8l1-7',fire:'M12 2c2 6-2 6 2 10 2-1 3-3 3-5 7 8 3 15-5 15S1 15 7 9c0 4 2 5 3 5-2-4 4-7 2-12',glass:'M4 3h16l-8 9L4 3zm8 9v9m-5 0h10',badge:'M12 2l3 5 6 1-4 5 1 7-6-3-6 3 1-7-4-5 6-1 3-5',scales:'M12 2v19m-6 0h12M3 6h18M5 6l-4 8h8L5 6zm14 0-4 8h8l-4-8',book:'M3 3h13a3 3 0 0 1 3 3v15H6a3 3 0 0 1-3-3V3zm0 14h16M7 7h8m-8 4h6',orders:'M8 3h8v4H8V3zm0 2H4v17h16V5h-4M8 12h8m-8 5h6',close:'M6 6l12 12M6 18 18 6',chevron:'m9 5 7 7-7 7',check:'m4 12 5 5L20 6',clock:'M12 7v5l3 2M2 12a10 10 0 1 0 20 0 10 10 0 1 0-20 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',help:'M9 8a3 3 0 1 1 5 3c-2 1-2 2-2 3m0 3h.01M2 12a10 10 0 1 0 20 0 10 10 0 1 0-20 0',save:'m4 12 5 5L20 6',car:'M3 10l2-6h14l2 6M2 10h20v8H2v-8zm2 8v3m16-3v3M5 14h2m10 0h2',weapon:'M3 6h18v5H10l-2 9H4l2-9H3V6zm7 5v4h4v-4',building:'M3 21h18M5 21V3h14v18M9 7h1m4 0h1M9 11h1m4 0h1m-5 10v-6h4v6',union:'M3 21V9l9-7 9 7v12M8 21v-7h8v7M3 9h18',warehouse:'M2 21V8l10-5 10 5v13M6 21V11h12v10m-12-6h12m-12 3h12',bank:'m2 8 10-6 10 6H2zm2 3v8m5-8v8m6-8v8m5-8v8M2 22h20',press:'M3 4h18v18H3V4zm4 4h4v6H7V8zm8 0h3m-3 4h3M7 18h11',sound:'M3 9h4l5-5v16l-5-5H3V9zm13-3c4 3 4 9 0 12m-2-9c2 1 2 5 0 6',crown:'m2 6 5 4 5-7 5 7 5-4-3 14H5L2 6zm3 11h14',arrow:'M4 12h16m-6-6 6 6-6 6'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${glyph[n]||glyph.building}"/></svg>`;
const portrait=(c,cls='')=>`<div class="portrait ${cls}" style="background-position:${(c.portrait%4)*100/3}% ${Math.floor(c.portrait/4)*100}%" role="img" aria-label="Portrait de ${esc(c.name)}"></div>`;
const types={restaurant:'Restaurant',pawn:'Prêteur sur gages',club:'Club privé',hotel:'Hôtel',store:'Commerce',bank:'Banque',pool:'Salle de billard',warehouse:'Entrepôt',bar:'Taverne',garage:'Garage',union:'Syndicat',press:'Imprimerie',factory:'Manufacture'};
const typeIcon=b=>({bank:'bank',warehouse:'warehouse',union:'union',press:'press',bar:'glass',club:'glass',garage:'car',restaurant:'glass',pool:'target'}[b.type]||'building');
let s,hasSave=false,saveError=false;try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw?.version===VERSION&&raw.crew?.length&&raw.buildings?.length===18&&raw.phase==='planning'){s=raw;hasSave=true;}}catch{}if(!s)s=newGame();
let view='map',selected=2,panel=false,hint=!hasSave,modalState=null,resolving=false,toastTimer,audio;
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(s));saveError=false;}catch{saveError=true;}};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function tone(success=true){if(!s.settings.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';o.frequency.setValueAtTime(success?440:160,audio.currentTime);o.frequency.exponentialRampToValueAtTime(success?660:100,audio.currentTime+.15);g.gain.setValueAtTime(.05,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.25);o.start();o.stop(audio.currentTime+.26);}catch{}}
const myOrders=()=>s.orders.filter(o=>o.side===0);
const status=c=>c.arrestedUntil>s.week?`Détenu · ${c.arrestedUntil-s.week} sem.`:c.readyAt>s.week?`Blessé · ${c.readyAt-s.week} sem.`:!available(s,c)?'En mission':'Disponible';
function nav(){return [['map','map','La ville'],['crew','people','La famille'],['orders','orders','Les ordres'],['finance','cash','Les affaires'],['journal','book','Le journal']].map(([id,ic,n])=>`<button class="navbtn ${view===id?'active':''}" data-view="${id}">${icon(ic)}<span>${n}</span>${id==='orders'?`<span class="count">${myOrders().length}</span>`:''}</button>`).join('');}
function render(){
 const active=crewOf(s,0).filter(c=>available(s,c)).length,playerScore=score(s,0),botScore=score(s,1),end=s.winner!==null;
 $('#app').innerHTML=`<header class="topbar"><div class="brand"><div class="monogram">G</div><div><h1>GANGSTER</h1><small>LA SUCCESSION · BLACKWATER, 1928</small></div></div><div class="topstats"><div class="topstat"><span>Trésorerie</span><strong>${money(s.cash[0]-reserved(s,0))}</strong><em>${reserved(s,0)?money(reserved(s,0))+' engagés':'disponibles'}</em></div><div class="topstat"><span>Hommes libres</span><strong>${active}<em>/ ${crewOf(s,0).length}</em></strong></div><div class="topstat"><span>Quartiers</span><strong class="good">${territories(s,0)}<em>/ 6</em></strong></div><div class="topstat"><span>Pression</span><strong class="${s.heat[0]>=60?'bad':'gold'}">${s.heat[0]}<em>/ 100</em></strong></div></div><div class="weekbox"><div class="weeklabel"><strong>SEMAINE ${Math.min(s.week,s.maxWeeks)} / ${s.maxWeeks}</strong><p>${end?'Le conseil a tranché':'Préparation des ordres'}</p></div><button class="btn primary" data-do="${end?'outcome':'end'}">${icon(end?'crown':'arrow')}${end?'Résultats':'Lancer la semaine'}</button><button class="iconbtn" data-do="settings" aria-label="Options">${icon('settings')}</button></div></header>
 <div class="workspace"><aside class="sidebar"><div class="side-title">VOTRE ORGANISATION</div>${nav()}<div class="rivalbox"><div class="eyebrow" style="margin-bottom:12px">LA GUERRE DE SUCCESSION</div><div class="flex">${portrait({portrait:0,name:'Enzo Moretti'})}<div><div class="name">Enzo Moretti</div><p class="small muted">Clan rival · ${s.difficulty==='calm'?'prudent':s.difficulty==='ruthless'?'impitoyable':'opportuniste'}</p></div></div><div class="influence"><div class="flex between small"><span class="good">Votre influence</span><span class="bad">Moretti</span></div><div class="flex between"><span class="score good">${playerScore}</span><span class="score bad">${botScore}</span></div><div class="influence-track"><i style="width:${playerScore/(playerScore+botScore||1)*100}%"></i><i style="flex:1"></i></div></div><div class="objective">Tenez <strong>4 quartiers pendant 2 semaines</strong>, ou ayez le plus d’influence à la fin.<div class="small gold" style="margin-top:8px">${s.hold[0]?'Votre domination : '+s.hold[0]+'/2 semaines':s.hold[1]?'Moretti domine : '+s.hold[1]+'/2 semaines':'La ville attend son nouveau parrain.'}</div></div></div><button class="navbtn" data-do="help" style="margin-top:15px">${icon('help')}Les règles</button><div class="save-note">${icon('save')}${saveError?'Sauvegarde indisponible':'Sauvegarde sur cet appareil'}</div></aside>
 <main class="main">${renderView()}</main><aside class="inspector ${panel?'open':''}">${renderInspector()}</aside></div>
 <div class="bottom-bar"><div><strong>Semaine ${Math.min(s.week,s.maxWeeks)} / ${s.maxWeeks}</strong><div class="small muted">${myOrders().length} ordre${myOrders().length>1?'s':''} · ${active} membre${active>1?'s':''} libre${active>1?'s':''}</div></div><button class="btn primary" data-do="${end?'outcome':'end'}">${end?'Résultats':'Lancer la semaine'} ${icon('arrow')}</button></div><nav class="mobile-nav" aria-label="Navigation principale">${[['map','map','Ville'],['crew','people','Famille'],['orders','orders','Ordres'+(myOrders().length?' · '+myOrders().length:'')],['finance','cash','Affaires'],['journal','book','Journal']].map(([id,i,n])=>`<button class="${view===id?'active':''}" data-view="${id}">${icon(i)}${n}</button>`).join('')}</nav>`;
}
function head(tag,title,right=''){return `<div class="mainhead"><div><div class="eyebrow">${tag}</div><h2>${title}</h2></div>${right}</div>`;}
function renderView(){
 if(view==='map')return `${head('LE TERRITOIRE', 'La ville est à prendre.',`<span class="small muted">18 établissements · 6 quartiers</span>`)}${hint?`<div class="step-help">${icon('hand')}<span><strong>Premier coup :</strong> sélectionne le Club Bellini, puis « Racketter ». Rose est douée pour convaincre.</span><button data-do="hide-hint" aria-label="Masquer le conseil">${icon('close')}</button></div>`:''}${renderMap()}<div class="eventbox">${icon('book','gold')}<div><h3>${esc(s.event.name)}</h3><p>${esc(s.event.desc)}</p></div></div><div class="roster-strip">${crewOf(s,0).map(c=>`<button class="roster-chip ${available(s,c)?'':'busy'}" data-person="${c.id}">${portrait(c)}<div><strong>${esc(c.name.split(' ')[0])}</strong><small>${status(c)}</small></div></button>`).join('')}</div>`;
 if(view==='crew')return `${head('LES VISAGES DE LA FAMILLE','Chacun a son rôle.',`<span class="tag gold">${crewOf(s,0).length} / 8 MEMBRES</span>`)}<div class="cards">${crewOf(s,0).map(crewCard).join('')}</div><h3 class="section-head">LES CONTACTS DISPONIBLES</h3><p class="small muted" style="margin-bottom:13px">Envoie un membre recruter. Les candidats sont aussi convoités par Moretti; les enquêtes en révèlent d’autres.</p><div class="cards recruit-cards">${s.candidates.filter(c=>c.known).map(c=>`<article class="crew-card"><div class="flex">${portrait(c,'large')}<div><h3>${esc(c.name)}</h3><div class="role">${esc(c.role)}</div><span class="small muted">${money(c.wage)} / semaine</span></div></div>${stats(c)}<button class="btn full" data-recruit="${c.id}" ${s.winner!==null?'disabled':''}>${icon('person')}Recruter · ${money(c.fee)}</button></article>`).join('')||'<div class="empty">Aucun contact disponible. Une enquête peut révéler de nouveaux candidats.</div>'}</div>`;
 if(view==='orders')return `${head('LE PLAN DE LA SEMAINE','Donnez vos ordres.',`<span class="tag gold">${myOrders().length} OPÉRATIONS</span>`)}<p class="small muted" style="margin-bottom:20px">Chaque homme participe à une seule opération. Les deux clans exécutent leurs plans pendant la même semaine. Les protections sont installées en premier.</p>${myOrders().length?myOrders().map(o=>orderCard(o,true)).join(''):'<div class="empty">Aucun ordre pour le moment.<br>Sélectionne un établissement sur la carte pour préparer une opération.<br><button class="btn" data-view="map" style="margin-top:15px">Retour à la ville</button></div>'}<div class="ledger-total">Fonds engagés : <strong class="gold">${money(reserved(s,0))}</strong></div>`;
 if(view==='finance')return `${head('LE LIVRE DE COMPTES','Faire tourner l’empire.')}<div class="summary-grid"><div class="summary-card"><span>Revenus automatiques*</span><strong class="good">${money(income(s,0))}</strong></div><div class="summary-card"><span>Salaires hebdomadaires</span><strong class="bad">${money(wages(s,0))}</strong></div><div class="summary-card"><span>À collecter</span><strong class="gold">${money(s.buildings.filter(b=>b.side===0&&!b.owned).reduce((n,b)=>n+b.stash,0))}</strong></div></div><p class="small muted" style="margin-bottom:20px">* Avant l’effet de l’événement. Les propriétés versent leurs revenus automatiquement. Les rackets nécessitent une collecte. Les salaires sont payés après les revenus.</p><div class="tablewrap"><table><thead><tr><th>Établissement</th><th>Relation</th><th>Revenu / sem.</th><th>Enveloppe</th><th></th></tr></thead><tbody>${s.buildings.filter(b=>b.side===0).map(b=>`<tr><td>${esc(b.name)}${b.illegal?'<br><span class="small gold">Speakeasy</span>':''}${b.closedUntil>=s.week?'<br><span class="small bad">Fermé</span>':''}</td><td>${b.owned?'Propriété':'Protection'}</td><td>${money(b.income+(b.illegal?100:0))}</td><td>${b.owned?'—':money(b.stash)}</td><td><button class="iconbtn" data-place="${b.id}" aria-label="Voir ${esc(b.name)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div><h3 class="section-head">POLICE & JUSTICE</h3><div class="eventbox">${icon('badge','gold')}<div><h3>Pression : ${s.heat[0]} / 100</h3><p>Dès 60, tes hommes risquent une arrestation en fin de semaine. Dès 80, tes bars clandestins risquent aussi une fermeture. La pression baisse naturellement de 6 par semaine.</p></div></div><div class="flex wrap" style="margin-top:15px"><button class="btn" data-action="bribe" data-bid="0">${icon('badge')}Soudoyer · 140 $</button><button class="btn" data-action="lawyer" data-bid="0" ${!crewOf(s,0).some(c=>c.arrestedUntil>s.week)?'disabled':''}>${icon('scales')}Avocat · 180 $</button></div>`;
 return `${head('LE JOURNAL DE BLACKWATER','La ville se souvient.')}<p class="small muted" style="margin-bottom:15px">Tes comptes rendus, du plus récent au plus ancien. Les opérations secrètes de Moretti restent inconnues.</p>${s.reports.length?s.reports.map(r=>`<section><h3 class="section-head">SEMAINE ${r.week}</h3>${r.entries.map(reportLine).join('')}</section>`).join(''):'<div class="empty">Le parrain vient de mourir.<br>La première page de cette histoire reste à écrire.</div>'}`;
}
function stats(c){return `<div class="stats">${[['force','Force'],['intimidation','Intimidation'],['business','Affaires'],['stealth','Discrétion']].map(([k,n])=>`<div class="statrow"><span>${n}</span><strong>${'●'.repeat(c[k])}<span style="opacity:.15">${'●'.repeat(5-c[k])}</span></strong></div>`).join('')}</div>`;}
function crewCard(c){return `<article class="crew-card"><div class="flex">${portrait(c,'large')}<div><h3>${esc(c.name)}</h3><div class="role">${esc(c.role)}</div><span class="pill ${available(s,c)?'':'bad'}">${status(c)}</span></div></div>${stats(c)}<div class="flex between small muted"><span>${money(c.wage)} / sem.</span><span class="${c.loyalty<60?'bad':''}">Loyauté ${c.loyalty} %</span></div><div class="divider"></div><div class="flex wrap"><button class="btn" data-equip="weapon" data-id="${c.id}" ${c.weapon||!available(s,c)||s.winner!==null?'disabled':''}>${icon('weapon')}${c.weapon?'Armé · +2 force':'Armer · 180 $'}</button><button class="btn" data-equip="car" data-id="${c.id}" ${c.car||!available(s,c)||s.winner!==null?'disabled':''}>${icon('car')}${c.car?'Véhicule attribué':'Voiture · 260 $'}</button></div></article>`;}
function orderCard(o,large=false){const a=ACTIONS[o.action];return `<article class="order-card"><div class="flex between"><div class="flex">${icon(a.icon,'gold')}<h3>${esc(a.name)}</h3></div><button class="iconbtn" data-cancel="${o.id}" aria-label="Annuler cet ordre">${icon('close')}</button></div><p>${esc(s.buildings[o.buildingId].name)}${o.action==='recruit'?' · '+esc(s.candidates.find(c=>c.id===o.recruitId)?.name??'Candidat'):''}</p><p>${o.crewIds.map(id=>esc(s.crew.find(c=>c.id===id)?.name.split(' ')[0]??'')).join(' + ')}${o.cost?' · '+money(o.cost):''}</p>${large?`<p style="margin-top:8px">${a.desc}</p>`:''}</article>`;}
function renderMap(){
 const fills=['#63937d','#ba735c'];let districts=DISTRICTS.map(d=>{const owner=districtOwner(s,d.id);return `<g><rect class="district" x="${d.x}" y="${d.y}" width="${d.w}" height="${d.h}" rx="5" fill="${owner===null?'#c4c5af':fills[owner]}" fill-opacity="${owner===null?'.28':'.2'}" stroke="${owner===null?'#929d87':fills[owner]}" stroke-width="1.5" stroke-dasharray="${owner===null?'4 4':'0'}"/><text x="${d.x+15}" y="${d.y+26}" class="district-name" fill="#344638">${d.name.toUpperCase()}</text><text x="${d.x+15}" y="${d.y+43}" class="district-tag" fill="#6d7868">${d.tag}</text><text x="${d.x+d.w-13}" y="${d.y+27}" text-anchor="end" font-size="12" fill="${owner===null?'#667260':owner===0?'#32654a':'#954b36'}">${owner===null?'DISPUTÉ':owner===0?'RUSSO':'MORETTI'}</text></g>`;}).join('');
 let places=s.buildings.map(b=>{const selectedOrder=myOrders().find(o=>o.buildingId===b.id);const color=b.side===null?'#e5e0cd':b.side===0?'#4c7862':'#9d5d4b';const text=b.side===null?'#3e503f':'#faf4e6';const closed=b.closedUntil>=s.week;return `<g class="place ${selected===b.id?'selected':''}" data-place="${b.id}" tabindex="0" role="button" aria-label="${esc(b.name)}, ${b.side===0?'votre réseau':b.side===1?'Moretti':'indépendant'}" transform="translate(${b.x},${b.y})"><title>${esc(b.name)} — ${b.side===0?'Votre réseau':b.side===1?'Clan Moretti':'Indépendant'}</title><rect x="-24" y="-24" width="${b.id%3===2?118:110}" height="75" rx="3" fill="#000" opacity=".10" transform="translate(2 3)"/><rect class="block" x="-24" y="-24" width="${b.id%3===2?118:110}" height="75" rx="3" fill="${color}" stroke="${b.side===null?'#8a9680':color}" stroke-width="1.2"/><rect class="selection" x="-19" y="-19" width="${b.id%3===2?108:100}" height="65" rx="2"/><g color="${text}" transform="translate(-13,-13)">${icon(b.hq?'crown':typeIcon(b))}</g><text x="72" y="0" text-anchor="end" fill="${text}" font-size="11">${b.hq?'QG':b.owned?'PROPRIÉTÉ':b.side!==null?'RACKET':'LIBRE'}</text><text x="-13" y="24" class="place-title" fill="${text}">${esc(b.name)}</text><text x="-13" y="40" class="place-label" fill="${text}" opacity=".8">${closed?'FERMÉ':b.side===0&&!b.owned?money(b.stash)+' à collecter':money(b.income)+' / sem.'}</text>${selectedOrder?`<circle cx="83" cy="-20" r="12" fill="#d8b976" stroke="#314433"/><text x="83" y="-16" text-anchor="middle" font-size="13" font-weight="700" fill="#2d432f">${myOrders().filter(o=>o.buildingId===b.id).length}</text>`:''}</g>`;}).join('');
 return `<div class="mapframe"><div class="maptoolbar"><strong>PLAN DE BLACKWATER</strong><div class="maplegend"><span><i></i>Russo</span><span><i class="red"></i>Moretti</span><span><i class="neutral"></i>Indépendant</span></div></div><div class="mapviewport"><svg class="map" viewBox="0 0 948 690" xmlns="http://www.w3.org/2000/svg" aria-label="Carte interactive de Blackwater"><defs><pattern id="grid" width="12" height="12" patternUnits="userSpaceOnUse"><path d="M12 0H0V12" fill="none" stroke="#718571" stroke-width=".3" opacity=".15"/></pattern><pattern id="water" width="14" height="8" patternUnits="userSpaceOnUse"><path d="M0 4h8" stroke="#7e9a8f" stroke-width=".7" opacity=".5"/></pattern></defs><rect width="948" height="690" fill="#dedac9"/><rect width="948" height="690" fill="url(#grid)"/><path d="M0 334H948" stroke="#adb9a9" stroke-width="26"/><path d="M0 334H948" stroke="#d7ddd0" stroke-width="19"/><path d="M318 0v660M630 0v660" stroke="#aeb8a6" stroke-width="13"/><path d="M318 0v660M630 0v660" stroke="#e9e7da" stroke-width="9"/>${districts}<text x="474" y="338" text-anchor="middle" fill="#758371" font-size="10" letter-spacing="5">BOULEVARD DU PARRAIN</text>${places}<rect x="0" y="668" width="948" height="22" fill="#aec1b6"/><rect x="0" y="668" width="948" height="22" fill="url(#water)"/><text x="474" y="659" text-anchor="middle" fill="#798d7d" font-size="10" letter-spacing="4">RIVIÈRE BLACKWATER</text><g transform="translate(920,665)" fill="#536f5a"><path d="M0-14l-4 9h8z"/><text x="0" y="-18" text-anchor="middle" font-size="9">N</text></g></svg></div><div class="mapnote"><span>2 établissements sur 3 = contrôle du quartier.</span><span>Sélectionnez un lieu pour agir.</span></div></div>`;
}
function renderInspector(){const b=s.buildings[selected];const own=b.side===0,enemy=b.side===1,intel=s.intel[0][b.id]?.expires>=s.week;const acts=b.side===null?['extort','buy','scout']:own?['collect','guard','buy','illegal','scout']:['attack','raid','sabotage','scout'];const permitted=acts.filter(a=>!(a==='collect'&&(b.owned||b.stash<=0))&&!(a==='buy'&&(b.owned||b.hq))&&!(a==='illegal'&&(!b.owned||b.illegal))&&!(b.hq&&['attack','raid','sabotage'].includes(a)));return `<div class="flex between"><span class="eyebrow">${DISTRICTS[b.district].name}</span><button class="iconbtn mobile-close" data-do="close-panel" aria-label="Fermer la fiche">${icon('close')}</button></div><h2 class="building-title">${esc(b.name)}</h2><p class="building-type">${types[b.type]}${b.hq?' · Quartier général':''}</p><div class="location-art">${icon(typeIcon(b))}<span>${String(b.id+1).padStart(2,'0')}</span><span class="tag ${own?'good':enemy?'bad':'gold'}" style="font-size:12px">${own?'VOTRE RÉSEAU':enemy?'MORETTI':'INDÉPENDANT'}</span></div><dl class="info-grid"><div><dt>Revenu / semaine</dt><dd>${money(b.income+(own||intel?b.illegal?100:0:0))}</dd></div><div><dt>${own&&!b.owned?'À collecter':'Acquisition'}</dt><dd>${own&&!b.owned?money(b.stash):b.owned?'Propriété':money(b.price)}</dd></div><div><dt>État</dt><dd class="${b.closedUntil>=s.week?'bad':''}">${b.closedUntil>=s.week?'Fermé':'En activité'}</dd></div><div><dt>Renseignements</dt><dd style="font-size:17px">${intel?'Dossier complet':own?'Sous contrôle':'À enquêter'}</dd></div></dl>${intel?`<p class="small muted">Résistance : ${b.resistance+(enemy?3:0)+(b.owned?1:0)} · ${b.illegal?'Activité clandestine':'Aucune activité clandestine'}${s.intel[0][b.id].bonus?' · +12 points sur la prochaine opération.':''}</p>`:''}${!reachable(s,0,b)?'<p class="small gold" style="margin-bottom:12px">Éloigné : une voiture est requise pour étendre ton réseau ici.</p>':''}<div class="divider"></div><div class="side-title">OPÉRATIONS DISPONIBLES</div><div class="actions">${permitted.map(a=>`<button class="action-btn" data-action="${a}" data-bid="${b.id}" ${s.winner!==null?'disabled':''}>${icon(ACTIONS[a].icon)}<span>${ACTIONS[a].name}</span><small>${cost(s,a,b)?money(cost(s,a,b)):a==='scout'?'+ info':'1–3 pers.'}</small></button>`).join('')}</div>${b.hq&&own?`<div class="divider"></div><button class="action-btn full" data-action="bribe" data-bid="${b.id}">${icon('badge')}<span>Soudoyer la police</span><small>140 $</small></button>`:''}<div class="divider"></div><div class="side-title">ORDRES SUR CE LIEU</div>${myOrders().filter(o=>o.buildingId===b.id).map(o=>orderCard(o)).join('')||'<p class="small muted">Aucun homme affecté pour le moment.</p>'}`;}
function reportLine(r){return `<div class="reportline">${icon(r.tone==='good'?'check':r.tone==='bad'?'bolt':'book',r.tone==='good'?'good':r.tone==='bad'?'bad':'gold')}<div><h3>${esc(r.title)}</h3><p>${esc(r.text)}</p></div></div>`;}
function openModal(html,state=null){modalState=state;const d=$('#modal');d.innerHTML=html;if(!d.open)d.showModal();d.scrollTop=0;}
function closeModal(){if(resolving)return;$('#modal').close();modalState=null;}
function modalHeader(tag,title){return `<div class="modal-header"><div><div class="eyebrow">${tag}</div><h2>${title}</h2></div><button class="iconbtn" data-do="close-modal" aria-label="Fermer">${icon('close')}</button></div>`;}
function operation(action,bid,recruitId=null,chosen=[]){if(s.winner!==null)return;const b=s.buildings[bid],a=ACTIONS[action];modalState={kind:'operation',action,bid,recruitId,chosen};const team=chosen.map(id=>s.crew.find(c=>c.id===id)),error=validation(s,0,action,bid,chosen,recruitId),chance=odds(s,0,action,b,team);openModal(`${modalHeader(DISTRICTS[b.district].name,a.name+' · '+esc(action==='recruit'?s.candidates.find(c=>c.id===recruitId)?.name??'Candidat':b.name))}<div class="modal-body"><p>${a.desc}</p><h3 class="section-head" style="margin-top:18px">AFFECTER DES MEMBRES <span class="muted">${chosen.length} / 3</span></h3>${crewOf(s,0).map(c=>`<button class="person-choice ${chosen.includes(c.id)?'selected':''}" data-choose="${c.id}" ${!available(s,c)?'disabled':''}>${portrait(c)}<div class="details"><strong>${esc(c.name)}</strong><small>${available(s,c)?`${{force:'Force',intimidation:'Intimidation',business:'Affaires',stealth:'Discrétion'}[a.skill]} ${c[a.skill]}${a.skill==='force'&&c.weapon?' +2':''} / 5${c.car?' · Voiture':''}`:status(c)}</small></div><span class="check">${chosen.includes(c.id)?'✓':''}</span></button>`).join('')}<div class="chancebox"><div class="flex between"><span class="small">${chance===100?'Résolution':'Chance estimée'}</span><strong>${chosen.length?chance===100?'Garantie*':chance+' %':'—'}</strong></div><p class="small" style="margin-top:5px">${chance===100?'* Si la cible reste disponible au moment de l’exécution.':'Les gardes adverses peuvent réduire cette estimation. Un échec peut blesser un membre.'}</p></div>${error&&chosen.length?`<p class="bad" role="status" style="color:var(--red)">${esc(error)}</p>`:''}</div><div class="modal-footer"><div><div class="small muted">Fonds engagés</div><strong class="gold">${money(cost(s,action,b,recruitId))}</strong></div><button class="btn primary" data-do="confirm-order" ${error?'disabled':''}>Donner l’ordre ${icon('arrow')}</button></div>`,{kind:'operation',action,bid,recruitId,chosen});}
function showHelp(){openModal(`${modalHeader('LE MANUEL DU PRÉTENDANT','Prendre la place du parrain.')}<div class="modal-body"><ol class="help-list"><li><strong>Prépare tes opérations.</strong> Sur la carte, sélectionne un commerce, une action et 1 à 3 membres. Chaque membre n’a qu’une affectation par semaine. Tu peux annuler un ordre avant de lancer.</li><li><strong>Fais rentrer l’argent.</strong> Le racket coûte surtout du temps. Ses enveloppes s’accumulent, jusqu’à 4 semaines de revenu. Les propriétés s’achètent et versent leur revenu automatiquement. Les collecteurs ajoutent 4 % par point d’Affaires du meilleur membre.</li><li><strong>Développe la famille.</strong> Recrute les candidats connus. Les enquêtes en découvrent d’autres. Les recrues arrivent la semaine suivante; 8 membres maximum. Armes : +2 de force, 180 $. Voiture : accès aux lieux éloignés, 260 $.</li><li><strong>Dispute la ville.</strong> 2 établissements sur 3 donnent le contrôle d’un quartier. Une prise de contrôle change le clan du commerce. Une descente vole de l’argent. Un sabotage supprime ses revenus pour 2 semaines. Les QG restent protégés.</li><li><strong>Anticipe Moretti.</strong> Il prépare ses propres ordres. Les gardes, enquêtes et contacts sont résolus en premier, puis les autres opérations dans un ordre aléatoire. Les gardes réduisent les chances adverses. Une cible qui change rend certains ordres caducs, sans dépense.</li><li><strong>Surveille la police.</strong> Dès 60 de pression, risque d’arrestation de 2 semaines. Dès 80, une descente peut aussi fermer un bar clandestin 2 semaines. Soudoyer réduit la pression de 22; un avocat libère les détenus pour la semaine suivante. Baisse naturelle : 6 par semaine.</li><li><strong>Paie les salaires.</strong> Une paie incomplète retire 25 de loyauté à tous. À zéro, le membre part. Une semaine payée restaure 5 de loyauté. Les blessés manquent la semaine suivante; les hommes arrêtés restent salariés.</li><li><strong>Remporte la succession.</strong> Tiens 4 quartiers pendant 2 semaines de suite. Sinon, le conseil compare l’influence à la fin : 2 par établissement, +2 par propriété, 5 par quartier, 1 par tranche de 500 $ et respect gagné lors des prises. L’argent départage une égalité.</li></ol><p class="small">Cette version est un prototype solo. Les règles sont des hypothèses de conception, pas une reproduction exacte du jeu original. La partie est sauvegardée dans ce navigateur, sur cet appareil.</p></div><div class="modal-footer"><span class="small muted">Pas de chronomètre : prends ton temps.</span><button class="btn primary" data-do="close-modal">À moi de jouer</button></div>`);}
function welcome(restart=false){openModal(`${modalHeader('BLACKWATER · OCTOBRE 1928',restart?'Une nouvelle succession.':'Le parrain est mort.')}<div class="modal-body intro"><p class="quote">« Les funérailles sont terminées. Maintenant, tout le monde attend de savoir à qui payer. »</p><p>Tu diriges le clan Russo. Enzo Moretti revendique lui aussi l’héritage. Les commerces hésitent, les anciens appuis se dispersent et la police reprend du terrain.</p><p><strong class="gold">Organise tes hommes. Reprends les affaires. Impose ton nom.</strong></p><div><label class="settings-row"><span>Durée de campagne</span><select id="weeks"><option value="16">16 semaines · complète</option><option value="8">8 semaines · découverte</option><option value="24">24 semaines · longue</option></select></label><label class="settings-row"><span>Enzo Moretti</span><select id="difficulty"><option value="normal">Opportuniste</option><option value="calm">Prudent</option><option value="ruthless">Impitoyable</option></select></label></div><p class="small">Un humain contre un bot. Aucun temps limite par tour. ${restart?'La sauvegarde actuelle sera remplacée.':'Première partie : les conseils te guident.'}</p></div><div class="modal-footer"><button class="btn" data-do="${restart?'close-modal':'help'}">${restart?'Annuler':'Lire les règles'}</button><button class="btn primary" data-do="new-game">Prendre les commandes ${icon('arrow')}</button></div>`,{kind:'welcome'});}
function settings(){openModal(`${modalHeader('OPTIONS','Votre partie.')}<div class="modal-body"><div class="settings-row"><span>Ambiance sonore discrète</span><button class="btn" data-do="sound">${icon('sound')}${s.settings.sound?'Activée':'Désactivée'}</button></div><div class="settings-row"><span>Règles et objectifs</span><button class="btn" data-do="help">Consulter</button></div><div class="settings-row"><span>Nouvelle campagne</span><button class="btn danger" data-do="restart">Recommencer</button></div><p class="settings-note">Sauvegarde automatique sur cet appareil. Les préférences du bot et la durée se choisissent au début d’une nouvelle campagne.</p><p class="settings-note">Gangster — La succession · Prototype 0.2</p></div><div class="modal-footer"><span class="small muted">Semaine ${Math.min(s.week,s.maxWeeks)} / ${s.maxWeeks}</span><button class="btn primary" data-do="close-modal">Revenir à la ville</button></div>`);}
function showOutcome(){const win=s.winner===0,draw=s.winner===2;openModal(`${modalHeader('LE CONSEIL DE LA FAMILLE','La succession est réglée.')}<div class="modal-body outcome">${icon('crown','gold')}<h2>${draw?'Un empire divisé.':win?'Le nouveau parrain, c’est vous.':'Moretti prend la tête de la famille.'}</h2><p>${esc(s.reason)}</p><div class="scorebig">${score(s,0)} <span class="muted" style="font-size:28px">—</span> ${score(s,1)}</div><div class="small muted">Votre influence · Influence de Moretti</div><div class="summary-grid" style="margin-top:25px"><div class="summary-card"><span>Quartiers</span><strong>${territories(s,0)} / 6</strong></div><div class="summary-card"><span>Établissements</span><strong>${s.buildings.filter(b=>b.side===0).length}</strong></div><div class="summary-card"><span>Trésorerie</span><strong>${money(s.cash[0])}</strong></div></div><p>${win?'Vos hommes ont gagné leur place. La ville connaît désormais votre nom.':'Chaque décision laisse une trace. Reprends le journal pour comprendre où la ville a basculé.'}</p></div><div class="modal-footer"><button class="btn" data-do="final-journal">Voir le journal</button><button class="btn primary" data-do="restart">Rejouer</button></div>`);}
async function endWeek(force=false){if(resolving||s.winner!==null)return;const free=crewOf(s,0).filter(c=>available(s,c)).length;if(free&&!force){openModal(`${modalHeader('AVANT DE SORTIR','Des hommes attendent encore.')}<div class="modal-body"><p>${free} membre${free>1?'s':''} n’${free>1?'ont':'a'} pas d’ordre. ${myOrders().length?'Le reste de ton plan est prêt.':'Aucune opération n’est préparée.'} Tu peux les affecter ou laisser la semaine se dérouler.</p></div><div class="modal-footer"><button class="btn" data-do="close-modal">Continuer à planifier</button><button class="btn primary" data-do="force-end">Lancer quand même</button></div>`);return;}
 const w=s.week;resolving=true;const reports=resolveWeek(s);save();render();openModal(`<div class="modal-header"><div><div class="eyebrow">SEMAINE ${w}</div><h2>Les hommes sont dans la rue.</h2></div></div><div class="modal-body resolve-stage"><div class="spinner"></div><div id="resolve-title" class="serif" style="font-size:21px">Les deux clans passent à l’action…</div><p id="resolve-text" style="margin-top:15px">Les ordres sont en cours d’exécution.</p><div id="resolve-progress" class="small gold" style="margin-top:20px"></div></div>`);
 const shown=reports.filter(r=>r.title!=='Les comptes de la semaine').slice(0,7);for(let i=0;i<shown.length;i++){await new Promise(r=>setTimeout(r,650));$('#resolve-title').textContent=shown[i].title;$('#resolve-text').textContent=shown[i].text;$('#resolve-progress').textContent=`${i+1} / ${shown.length}`;tone(shown[i].tone!=='bad');}await new Promise(r=>setTimeout(r,400));resolving=false;
 openModal(`${modalHeader('SEMAINE '+w+' · COMPTE RENDU','Ce qui s’est passé.')}<div class="modal-body"><div class="flex between" style="margin-bottom:12px"><span class="small">Votre influence <strong class="good">${score(s,0)}</strong></span><span class="small">Moretti <strong class="bad">${score(s,1)}</strong></span></div>${reports.map(reportLine).join('')}</div><div class="modal-footer"><span class="small muted">${s.winner===null?`${s.maxWeeks-w} semaines restantes`:'La partie est terminée'}</span><button class="btn primary" data-do="${s.winner===null?'close-modal':'outcome'}">${s.winner===null?'Préparer la suite':'Le verdict du conseil'} ${icon('arrow')}</button></div>`);
}
document.addEventListener('click',e=>{
 const t=e.target.closest('button,[data-place]');if(!t||t.disabled||resolving)return;
 if(t.dataset.view){view=t.dataset.view;panel=false;render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(t.dataset.place!==undefined){selected=Number(t.dataset.place);panel=true;view='map';const scroll=$('.mapviewport')?.scrollLeft??0;render();if($('.mapviewport'))$('.mapviewport').scrollLeft=scroll;return;}
 if(t.dataset.action){operation(t.dataset.action,Number(t.dataset.bid));return;}
 if(t.dataset.recruit){operation('recruit',0,Number(t.dataset.recruit));return;}
 if(t.dataset.person){const c=s.crew.find(c=>c.id===Number(t.dataset.person));openModal(`${modalHeader('LA FAMILLE',esc(c.name))}<div class="modal-body">${crewCard(c)}</div><div class="modal-footer"><span class="small muted">Une affectation par semaine.</span><button class="btn primary" data-do="close-modal">Fermer</button></div>`);return;}
 if(t.dataset.equip){if(equip(s,Number(t.dataset.id),t.dataset.equip)){save();render();closeModal();toast(t.dataset.equip==='weapon'?'Équipement attribué : +2 en force.':'Véhicule attribué : les lieux éloignés sont accessibles.');tone();}else toast('Fonds insuffisants ou membre indisponible.');return;}
 if(t.dataset.cancel){cancelOrder(s,Number(t.dataset.cancel));save();render();toast('Ordre annulé. Membres et fonds libérés.');return;}
 if(t.dataset.choose){const m=modalState,id=Number(t.dataset.choose);if(m?.kind!=='operation')return;let a=m.chosen.includes(id)?m.chosen.filter(i=>i!==id):m.chosen.length<3?[...m.chosen,id]:m.chosen;const scroll=$('#modal').scrollTop;operation(m.action,m.bid,m.recruitId,a);$('#modal').scrollTop=scroll;return;}
 const d=t.dataset.do;
 if(d==='close-modal')closeModal();else if(d==='close-panel'){panel=false;render();}else if(d==='hide-hint'){hint=false;render();}else if(d==='help')showHelp();else if(d==='settings')settings();else if(d==='restart')welcome(true);else if(d==='outcome')showOutcome();else if(d==='final-journal'){closeModal();view='journal';panel=false;render();}
 else if(d==='sound'){s.settings.sound=!s.settings.sound;save();tone();settings();}
 else if(d==='new-game'){const weeks=Number($('#weeks').value),difficulty=$('#difficulty').value;const sound=s.settings.sound;s=newGame({weeks,difficulty});s.settings.sound=sound;hint=true;view='map';selected=2;panel=false;save();closeModal();render();toast('La ville attend vos ordres.');}
 else if(d==='confirm-order'){const m=modalState;if(!m||m.kind!=='operation')return;const result=addOrder(s,0,m.action,m.bid,m.chosen,m.recruitId);if(!result.ok){toast(result.error);return;}save();closeModal();panel=false;render();tone();toast('Ordre ajouté. Les hommes sont prêts.');}
 else if(d==='end')endWeek();else if(d==='force-end')endWeek(true);
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.place')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
$('#modal').addEventListener('cancel',e=>{if(resolving)e.preventDefault();else modalState=null;});
render();if(!hasSave)welcome();
const context=document.modelContext;if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'read_gangster_state',title:'Lire la partie',description:'Lire les informations accessibles au joueur humain, sans dévoiler les ordres du bot.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>publicState(s)})).catch(()=>{});Promise.resolve(context.registerTool({name:'stage_gangster_order',title:'Préparer un ordre',description:'Ajouter un ordre à la planification visible, sans lancer la semaine.',inputSchema:{type:'object',properties:{action:{type:'string',enum:Object.keys(ACTIONS)},buildingId:{type:'integer',minimum:0,maximum:17},crewIds:{type:'array',items:{type:'integer'},minItems:1,maxItems:3},recruitId:{type:'integer'}},required:['action','buildingId','crewIds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.action!=='string'||!Number.isInteger(input.buildingId)||!Array.isArray(input.crewIds)||!input.crewIds.every(Number.isInteger))throw new Error('Ordre invalide');if(resolving)throw new Error('Semaine en cours');const r=addOrder(s,0,input.action,input.buildingId,input.crewIds,input.recruitId??null);if(!r.ok)throw new Error(r.error);save();render();return {ok:true,order:r.order};}})).catch(()=>{});}catch{}}
